Code Snippet:
"use client";

export default function Clock() {
  return <time>{new Date().toISOString()}</time>;
}

Correct Answer:
Computing time in both initial renders can disagree. Use a matching initial placeholder and update on the client.

"use client";
import { useEffect, useState } from "react";

export default function Clock() {
  const [time, setTime] = useState("");
  useEffect(() => { setTime(new Date().toISOString()); }, []);
  return <time>{time}</time>;
}

